import{_ as e,o as d,c as l,a2 as a}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"インスタント機能とキーワード拡張","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/instant-answers.md","filePath":"ja-JP/user-guide/instant-answers.md","lastUpdated":1788366161000}'),o={name:"ja-JP/user-guide/instant-answers.md"};function s(n,t,i,r,c,g){return d(),l("div",null,[...t[0]||(t[0]=[a(`<h1 id="インスタント機能とキーワード拡張" tabindex="-1">インスタント機能とキーワード拡張 <a class="header-anchor" href="#インスタント機能とキーワード拡張" aria-label="Permalink to &quot;インスタント機能とキーワード拡張&quot;">​</a></h1><p>Lertaro はローカルファイルの検索だけでなく、即座に計算結果を返す機能や各種システムツール、キーワード連動型の拡張プラグインを標準搭載しています。ファイル検索の完了を待つことなく、コマンドを入力するだけで即座に結果を得られます。</p><h2 id="_1-プレフィックス不要の即時機能" tabindex="-1">1. プレフィックス不要の即時機能 <a class="header-anchor" href="#_1-プレフィックス不要の即時機能" aria-label="Permalink to &quot;1. プレフィックス不要の即時機能&quot;">​</a></h2><p>キーワードを入力しなくても、入力した文字列が特定のパターンに一致すると自動的に起動します。</p><h3 id="計算機と基数変換" tabindex="-1">計算機と基数変換 <a class="header-anchor" href="#計算機と基数変換" aria-label="Permalink to &quot;計算機と基数変換&quot;">​</a></h3><p>検索ボックスに計算式を直接入力すると、計算結果が 1 行目にリアルタイムで表示されます。<code>Enter</code> キーを押すと計算結果がクリップボードにコピーされます。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>12 * (4 + 3)</span></span>
<span class="line"><span>100 * (1 - 0.15)</span></span></code></pre></div><p>進数変換にも標準で対応しています。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>255 to hex</span></span>
<span class="line"><span>0xFF to dec</span></span>
<span class="line"><span>101010 to bin</span></span></code></pre></div><h3 id="環境変数の展開と検索" tabindex="-1">環境変数の展開と検索 <a class="header-anchor" href="#環境変数の展開と検索" aria-label="Permalink to &quot;環境変数の展開と検索&quot;">​</a></h3><ul><li><strong>変数の展開</strong>：<code>%NAME%</code>（例: <code>%PATH%</code>、<code>%APPDATA%</code>）を入力すると、変数の実際の値が表示されます。<code>PATH</code> などの複数のパスを含む変数は、見やすいリスト形式に自動展開されます。</li><li><strong>変数のあいまい検索</strong>：<code>%</code> に続けてキーワードを入力する（例: <code>%temp</code>）と、名前にその文字を含むシステム/ユーザー環境変数を検索できます。</li></ul><h3 id="コマンドの直接実行" tabindex="-1">コマンドの直接実行 <a class="header-anchor" href="#コマンドの直接実行" aria-label="Permalink to &quot;コマンドの直接実行&quot;">​</a></h3><p>ターミナルを開かずに検索ボックスから直接コマンドを実行できます。</p><ul><li><code>#&lt;コマンド&gt;</code>：コマンドプロンプトを開き、<strong>管理者権限で実行</strong>します（例: <code>#sfc /scannow</code> や <code>#net start Lertaro.Service</code>）。</li><li><code>$&lt;コマンド&gt;</code>：コマンドプロンプトを開き、<strong>通常のユーザー権限で実行</strong>します（例: <code>$ping 1.1.1.1</code> や <code>$ipconfig /all</code>）。</li></ul><h3 id="web-サイトの-url-直開き" tabindex="-1">Web サイトの URL 直開き <a class="header-anchor" href="#web-サイトの-url-直開き" aria-label="Permalink to &quot;Web サイトの URL 直開き&quot;">​</a></h3><p><code>http://</code> または <code>https://</code> で始まる URL を入力または貼り付けて <code>Enter</code> を押すと、既定のブラウザでそのページが即座に開きます。<code>example.com</code> のような有効なプロトコルなしの Web アドレスを入力すると、クイック検索ウィンドウに <code>https://...</code> と <code>http://...</code> の 2 つの即時結果が生成されます。各結果はブラウザーで開く案内を 2 行形式で表示し、検索ボックスの内容は変更されません。すでにプロトコルを含む URL は 1 件の結果として表示されます。</p><h3 id="クイック検索ウィンドウへのクリップボード文字列の取り込み" tabindex="-1">クイック検索ウィンドウへのクリップボード文字列の取り込み <a class="header-anchor" href="#クイック検索ウィンドウへのクリップボード文字列の取り込み" aria-label="Permalink to &quot;クイック検索ウィンドウへのクリップボード文字列の取り込み&quot;">​</a></h3><p>入力が事前設定されていない状態でクイック検索ウィンドウを呼び出すと、クリップボードが空でなく、同じウィンドウで直前に取り込んだ値と異なる場合に自動入力して全選択します。同じ値は繰り返し取り込まず、URI やフル検索ウィンドウから戻った際の事前入力も上書きしません。</p><h2 id="_2-キーワード起動機能-内蔵プラグイン" tabindex="-1">2. キーワード起動機能（内蔵プラグイン） <a class="header-anchor" href="#_2-キーワード起動機能-内蔵プラグイン" aria-label="Permalink to &quot;2. キーワード起動機能（内蔵プラグイン）&quot;">​</a></h2><p>短い <strong>トリガーキーワード + スペース</strong> の後にクエリを入力することで、専用プラグインの機能を呼び出せます。各キーワードは <a href="./settings/plugins.html"><strong>設定 → プラグイン</strong></a> で自由に変更可能です。</p><table tabindex="0"><thead><tr><th style="text-align:left;">既定のキーワード</th><th style="text-align:left;">プラグイン名</th><th style="text-align:left;">機能概要と活用シーン</th><th style="text-align:left;">入力例</th></tr></thead><tbody><tr><td style="text-align:left;"><code>ps</code></td><td style="text-align:left;"><strong>プロセス管理</strong></td><td style="text-align:left;">実行中のプロセスを名前、PID、ウィンドウタイトル（ピンイン対応）で検索し、Enter キーで即座に終了。</td><td style="text-align:left;"><code>ps chrome</code> や <code>ps 1234</code></td></tr><tr><td style="text-align:left;"><code>win</code></td><td style="text-align:left;"><strong>ウィンドウ切り替え</strong></td><td style="text-align:left;">開いているウィンドウを検索して切り替え。バックグラウンドでのリアルタイムサムネイル取得に対応。</td><td style="text-align:left;"><code>win code</code> や <code>win ブラウザ</code></td></tr><tr><td style="text-align:left;"><code>bb</code></td><td style="text-align:left;"><strong>ブラウザーのブックマーク</strong></td><td style="text-align:left;">Chrome、Edge、Firefox などのブックマークを検索します。</td><td style="text-align:left;"><code>bb github</code></td></tr><tr><td style="text-align:left;"><code>bh</code></td><td style="text-align:left;"><strong>ブラウザーの閲覧履歴</strong></td><td style="text-align:left;">Chrome、Edge、Firefox などの閲覧履歴を検索します。</td><td style="text-align:left;"><code>bh github</code></td></tr><tr><td style="text-align:left;"><code>set</code></td><td style="text-align:left;"><strong>設定検索</strong></td><td style="text-align:left;">Lertaro 内部のすべての設定項目をあいまい検索。選択すると該当する設定画面へ直接ジャンプしてハイライト。</td><td style="text-align:left;"><code>set ホットキー</code> や <code>set あいまい</code></td></tr><tr><td style="text-align:left;"><code>flow</code></td><td style="text-align:left;"><strong>Flow プラグインブリッジ</strong></td><td style="text-align:left;">読み込まれている Flow.Launcher プラグインとそのトリガーワードを一覧表示。</td><td style="text-align:left;"><code>flow</code></td></tr><tr><td style="text-align:left;"><code>cs</code></td><td style="text-align:left;"><strong>コンテンツ検索</strong></td><td style="text-align:left;">インデックス済みローカル文書の本文を検索し、スニペット付きでファイルを表示。</td><td style="text-align:left;"><code>cs プロジェクト計画</code></td></tr></tbody></table><h2 id="_3-web-検索エンジン連携" tabindex="-1">3. Web 検索エンジン連携 <a class="header-anchor" href="#_3-web-検索エンジン連携" aria-label="Permalink to &quot;3. Web 検索エンジン連携&quot;">​</a></h2><p>Web 検索プラグインには主要な検索エンジンのショートカットが組み込まれており、プレフィックスに続けて検索語を入力するとブラウザで検索を実行できます。</p><table tabindex="0"><thead><tr><th style="text-align:left;">キーワード</th><th style="text-align:left;">検索エンジン</th><th style="text-align:left;">入力例</th><th style="text-align:left;">説明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>bd</code></td><td style="text-align:left;">百度 (Baidu)</td><td style="text-align:left;"><code>bd 深度学習</code></td><td style="text-align:left;">Baidu で検索</td></tr><tr><td style="text-align:left;"><code>g</code></td><td style="text-align:left;">Google</td><td style="text-align:left;"><code>g lertaro github</code></td><td style="text-align:left;">Google で検索</td></tr><tr><td style="text-align:left;"><code>bing</code></td><td style="text-align:left;">Bing</td><td style="text-align:left;"><code>bing マイクロソフト ドキュメント</code></td><td style="text-align:left;">Bing で検索</td></tr><tr><td style="text-align:left;"><code>gh</code></td><td style="text-align:left;">GitHub</td><td style="text-align:left;"><code>gh Lertaro</code></td><td style="text-align:left;">GitHub リポジトリを直接検索</td></tr><tr><td style="text-align:left;"><code>wiki</code></td><td style="text-align:left;">Wikipedia</td><td style="text-align:left;"><code>wiki 量子力学</code></td><td style="text-align:left;">Wikipedia の項目を検索</td></tr><tr><td style="text-align:left;"><code>yt</code></td><td style="text-align:left;">YouTube</td><td style="text-align:left;"><code>yt lofi hip hop</code></td><td style="text-align:left;">YouTube 動画を検索</td></tr></tbody></table><p><strong>設定 → プラグイン → Web 検索 → 設定</strong> で検索エンジンの追加、編集、削除、URL テンプレートの変更が可能です。</p><h2 id="_4-インスタント翻訳" tabindex="-1">4. インスタント翻訳 <a class="header-anchor" href="#_4-インスタント翻訳" aria-label="Permalink to &quot;4. インスタント翻訳&quot;">​</a></h2><p>既定のトリガーワード <code>tr</code> の後にテキストを入力すると、Lertaro で現在選択されている UI 言語に自動翻訳されます。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tr Hello, how are you today?</span></span></code></pre></div><ul><li>入力中に非同期で翻訳結果が表示され、<code>Enter</code> キーで訳文をコピーできます。</li><li><strong>設定 → プラグイン → 翻訳 → 設定</strong> でトリガーワードの変更が可能です。</li></ul><h2 id="_5-ファイルフィルター" tabindex="-1">5. ファイルフィルター <a class="header-anchor" href="#_5-ファイルフィルター" aria-label="Permalink to &quot;5. ファイルフィルター&quot;">​</a></h2><p><strong>設定 → プラグイン → ファイルフィルター → 設定</strong> で、特定のフォルダーや拡張子に限定した専用の検索スコープを作成できます。</p><ul><li><strong>対象フォルダーの指定</strong>：特定の作業ディレクトリ（例: <code>D:\\Engineering\\Drawings</code>）を再帰的にスキャン。</li><li><strong>拡張子ルールの指定</strong>：<code>*.dwg;*.dxf</code> や <code>*.pdf;*.docx</code> などのパターンを指定。</li><li><strong>トリガーキーワードの割り当て</strong>：専用のプレフィックス（例: <code>cad</code>）を割り当て、<code>cad パーツ図</code> のように特定の業務ファイルだけを切り離して検索可能。</li></ul><h2 id="_6-カスタムコマンド" tabindex="-1">6. カスタムコマンド <a class="header-anchor" href="#_6-カスタムコマンド" aria-label="Permalink to &quot;6. カスタムコマンド&quot;">​</a></h2><p><strong>設定 → プラグイン → カスタムコマンド → 設定</strong> で、よく使うスクリプトやツール、外部アプリを簡単なコマンドとして登録できます。</p><ul><li><strong>パラメータプレースホルダー</strong>：位置プレースホルダー <code>%s1</code>、<code>%s2</code>... や、キーワード以降の全文を受け取る <code>%s</code> に対応。</li><li><strong>クイックナビゲーションへの登録</strong>：「クイックナビゲーションに表示」を有効にすると、<a href="./hotkeys.html#3-クイックナビゲーションマウス操作"><strong>クイックナビゲーション</strong></a> メニューにピン留めされ、<code>/</code> を使った多階層分類（例: <code>開発ツール/サービス再起動</code>）も可能です。</li></ul>`,35)])])}const x=e(o,[["render",s]]);export{p as __pageData,x as default};
